# Test of the Git LFS rules of the art files (D926, AR7-c), without network and without touching the real index.
# - a file under Content/Art and a source file under ArtSource are LFS (filter, diff, merge = lfs, not text) and lockable;
# - files outside those folders stay plain git (tables regenerated by agents, older FBX of Content/Knight, code);
# - every tracked file under Content/Art and ArtSource is an LFS pointer in HEAD (no raw .uasset left behind);
# - a NEW file under Content/Art is stored as an LFS pointer by "git add" (checked in a temporary index).
# Exit code 0 = green, 1 = red.
param([string]$Root = (Resolve-Path (Join-Path $PSScriptRoot '..\..')).Path)
$ErrorActionPreference = 'Continue'
$fails = 0
function Fail([string]$Text) { Write-Output "FAIL $Text"; $script:fails++ }
function Ok([string]$Text) { Write-Output "ok $Text" }
function Get-Attr([string]$Path, [string]$Name) {
    $line = @(& git.exe -C $Root check-attr $Name -- $Path 2>&1 | ForEach-Object { "$_" })[0]
    if ($line -match ': [^:]+: (\S+)$') { return $Matches[1] }
    return "?($line)"
}
function Assert-Attr([string]$Path, [string]$Name, [string]$Want) {
    $got = Get-Attr $Path $Name
    if ($got -ne $Want) { Fail "$Path $Name = '$got', want '$Want'" } else { Ok "$Path $Name = $got" }
}

& git.exe lfs version *> $null
if ($LASTEXITCODE -ne 0) { Write-Output 'FAIL git-lfs is not installed (https://git-lfs.com, then "git lfs install")'; exit 1 }

# 1. LFS and lockable inside the art folders.
$artPaths = @('Content/Art/Units/Probe/DA_Art_Probe.uasset', 'Content/Art/Units/Probe/SM_Probe.uasset', 'Content/Art/Units/Probe/T_Probe.png',
              'ArtSource/Units/Probe/Probe.fbx', 'ArtSource/Units/Probe/Probe.psd', 'ArtSource/Units/Probe/T_Probe_Diffuse.tga')
foreach ($path in $artPaths) {
    Assert-Attr $path 'filter' 'lfs'
    Assert-Attr $path 'diff' 'lfs'
    Assert-Attr $path 'merge' 'lfs'
    Assert-Attr $path 'text' 'unset'
    Assert-Attr $path 'lockable' 'set'
}

# 2. Plain git outside them.
foreach ($path in @('Content/Units/UnitTypes.uasset', 'Content/Knight/Probe.fbx', 'Source/HeroesOfLiberty/Art/HOLArtVisual.h', 'Docs/ARTISTES.md', 'Tools/Data/ArtVisuals.csv')) {
    Assert-Attr $path 'filter' 'unspecified'
    Assert-Attr $path 'lockable' 'unspecified'
}

# 2b. Editor kit of the artists (D927): LFS without lock (only the main session writes it), its source commit stays text.
foreach ($path in @('ArtistBinaries/Win64/UnrealEditor-HeroesOfLiberty.dll', 'ArtistBinaries/Win64/UnrealEditor.modules')) {
    Assert-Attr $path 'filter' 'lfs'
    Assert-Attr $path 'lockable' 'unspecified'
}
Assert-Attr 'ArtistBinaries/Win64/source_commit.txt' 'filter' 'unspecified'
    Assert-Attr 'ArtistBinaries/Win64/source_commit.txt' 'diff' 'unspecified'

# 3. Every tracked art file is a pointer in HEAD.
$tracked = @(& git.exe -C $Root ls-files -- Content/Art ArtSource 2>&1 | ForEach-Object { "$_" } | Where-Object { $_ -and $_ -notmatch '(^|/)\.gitkeep$|README' })
$pointers = @{}
foreach ($line in @(& git.exe -C $Root lfs ls-files -n 2>&1 | ForEach-Object { "$_" })) { $pointers[$line.Trim()] = $true }
$raw = @($tracked | Where-Object { -not $pointers.ContainsKey($_) })
if ($tracked.Count -eq 0) { Fail 'no tracked file under Content/Art (expected the DA_Art)' }
elseif ($raw.Count) { Fail "$($raw.Count)/$($tracked.Count) art files are not LFS pointers in HEAD, first: $($raw[0])" }
else { Ok "$($tracked.Count) art files are LFS pointers in HEAD" }

# 4. A new art file goes in as a pointer (temporary index: the real index and HEAD stay untouched).
$probeDir = Join-Path $Root 'Content\Art\_LfsProbe'
$probeRel = 'Content/Art/_LfsProbe/probe.uasset'
$tmpIndex = Join-Path ([IO.Path]::GetTempPath()) ("hol_lfs_probe_" + [guid]::NewGuid().ToString('N') + '.idx')
$oldIndex = $env:GIT_INDEX_FILE
try {
    New-Item -ItemType Directory -Force $probeDir | Out-Null
    $bytes = New-Object byte[] 4096; (New-Object Random 926).NextBytes($bytes)
    [IO.File]::WriteAllBytes((Join-Path $probeDir 'probe.uasset'), $bytes)
    $env:GIT_INDEX_FILE = $tmpIndex
    & git.exe -C $Root add -f -- $probeRel 2>&1 | Out-Null
    $first = @(& git.exe -C $Root cat-file -p ":$probeRel" 2>&1 | ForEach-Object { "$_" })[0]
    if ($first -eq 'version https://git-lfs.github.com/spec/v1') { Ok "new file $probeRel stored as an LFS pointer" }
    else { Fail "new file $probeRel stored raw (not an LFS pointer)" }
} finally {
    if ($null -eq $oldIndex) { Remove-Item Env:GIT_INDEX_FILE -ErrorAction SilentlyContinue } else { $env:GIT_INDEX_FILE = $oldIndex }
    Remove-Item -Recurse -Force $probeDir -ErrorAction SilentlyContinue
    Remove-Item -Force $tmpIndex -ErrorAction SilentlyContinue
}

if ($fails) { Write-Output "art_lfs_test RED : $fails failure(s)"; exit 1 }
Write-Output 'art_lfs_test GREEN'
exit 0
